        List<Position> collectedGems = new ArrayList<>();
        List<Position> collectedExtraLives = new ArrayList<>();

        // Check what's in the target cell
        if (targetEntityCell.getEntity() instanceof Mine) {
            // Player dies - don't mutate the board
            return new MoveResult.Valid.Dead(newPos, newPos);
        }

        // Collect items if present
        if (targetEntityCell.getEntity() instanceof Gem) {
            collectedGems.add(newPos);
